def temp_val(base,index):
    suffix = ["","","_Online", "_Banker_Assisted", "", "_Online", "_Banker_Assisted"]
    prefix = ["", "Consumer_", "Consumer_", "Consumer_", "Business_", "Business_", "Business_",  ]

    if index == 0:
        return base
    
    return prefix[index]+base+suffix[index]

